const supportMessagePrefix =
  "A user had a question the bot couldn't answer. Here's their message: ";

function prepareHumanSupport({ chatInput }) {
  if (typeof chatInput !== "string" || !chatInput.trim())
    throw new Error("Supply the question or support request as text.");
  const hasEmail = /([a-zA-Z0-9._-]+@[a-zA-Z0-9._-]+\.[a-zA-Z0-9_-]+)/i.test(chatInput);
  const text = supportMessagePrefix + chatInput;
  if (hasEmail && text.length > 40000)
    throw new Error("The support message exceeds the 40,000-character budget.");
  return { hasEmail, text };
}

return $input
  .all()
  .map((item, index) => ({ json: prepareHumanSupport(item.json), pairedItem: { item: index } }));

const missingEmailResponse =
  "I'm sorry I don't know the answer. Please repeat your question and include your email address so I can request help.";
const supportNotifiedResponse = "Thank you for getting in touch. I've messaged a human to help.";

function humanSupportReply({ delivered, ts, channelId }) {
  if (!delivered) return { response: missingEmailResponse };
  if (typeof ts !== "string" || !ts.trim() || typeof channelId !== "string" || !channelId.trim())
    throw new Error("Slack did not acknowledge the support message.");
  return { response: supportNotifiedResponse };
}

return $input.all().map((item, index) => ({
  json: humanSupportReply({
    delivered: true,
    ts: item.json.message_timestamp,
    channelId: item.json.channel,
  }),
  pairedItem: { item: index },
}));

